  "Your document will be securely uploaded and the agent notified immediately. Files are stored privately and only visible to authorized parties in the transaction.": "Su documento se subirá de forma segura y se le avisará al agente de inmediato. Los archivos se guardan de forma privada y solo los ven las personas autorizadas en la transacción.",
