  "Review your closing figures": "Revise sus cifras de cierre",
  "You'll get a settlement statement with your final numbers — review it and ask your agent about anything unclear.": "Recibirá una declaración de cierre con sus números finales — revísela y pregúntele a su agente sobre cualquier cosa que no esté clara.",
  "Lead-paint disclosure": "Divulgación sobre pintura con plomo",
