  "Reading the executed contract — checking terms, dates, and signatures. This can take up to a minute…": "Leyendo el contrato ejecutado — verificando términos, fechas y firmas. Esto puede tardar hasta un minuto…",
  "✅ Executed contract verified — signed properly": "✅ Contrato ejecutado verificado — firmado correctamente",
