  "✅ Saved. This form now goes out with EVERY offer packet, with the buyer's name filled in automatically.": "✅ Guardado. Este formulario ahora se incluirá en CADA paquete de oferta, con el nombre del comprador completado automáticamente.",
  " rider saved. It will be attached to this and every future offer packet, with the buyer/seller/property stamped on automatically.": " anexo guardado. Se adjuntará a este y a todos los futuros paquetes de oferta, con el comprador/vendedor/propiedad sellados automáticamente.",
