  "First offer? Start here — Express offer (4 questions)": "¿Primera oferta? Empiece aquí — Oferta Rápida (4 preguntas)",
  "Answer 4 questions — the app fills everything else with standard Florida terms (15-day inspection, deposit due in 3 days, seller pays deed stamps, possession at closing…). You review it all before anything is sent.": "Responda 4 preguntas — la aplicación completa todo lo demás con los términos estándar de Florida (inspección de 15 días, depósito vence en 3 días, el vendedor paga los sellos de la escritura, posesión al cierre…). Usted revisa todo antes de que se envíe algo.",
