  "Tip: upload the MLS sheet on the next screen (or before sending) so the property, seller, and listing agent fill in automatically.": "Consejo: suba la hoja de MLS en la siguiente pantalla (o antes de enviar) para que la propiedad, el vendedor y el agente de listado se completen automáticamente.",
