  "Print the listing detail sheet from your MLS as a PDF and upload it here. We'll fill in the property address, list price, year built, HOA, listing agent contact, and more — so you don't have to type it.": "Imprima la hoja de detalle del listado desde su MLS como PDF y súbala aquí. Completaremos la dirección de la propiedad, precio de lista, año de construcción, HOA, contacto del agente de listado y más — para que no tenga que escribirlo.",
