  "Generate the offer packet": "Generar el paquete de oferta",
  "Builds one PDF: an offer summary, the filled Vacant Land Contract (VAC-15), any broker forms, and the buyer's proof of funds. Download and review before marking the offer Ready.": "Crea un solo PDF: un resumen de la oferta, el Contrato de Terreno Baldío (VAC-15) completado, cualquier formulario de correduría y la prueba de fondos del comprador. Descargue y revise antes de marcar la oferta como Lista.",
  "Builds one PDF: an offer summary, the filled AS-IS contract, the selected addenda, and the buyer's pre-approval letter. Download and review before marking the offer Ready.": "Crea un solo PDF: un resumen de la oferta, el contrato AS-IS completado, los anexos seleccionados y la carta de pre-aprobación del comprador. Descargue y revise antes de marcar la oferta como Lista.",
