  "Based on your answers, these should likely be attached:": "Según sus respuestas, probablemente deberían adjuntarse estos:",
  "In Florida, a checked addendum becomes part of the contract — select them above (or proceed if intentionally omitted).": "En Florida, un anexo marcado pasa a formar parte del contrato — selecciónelos arriba (o continúe si se omitió intencionalmente).",
  "Check these selections:": "Revise estas selecciones:",
  "This property is in a Special Flood Hazard Area — a lender will require flood insurance, and it can be costly. Warn the buyer and factor it into their budget.": "Esta propiedad está en un Área Especial de Riesgo de Inundación — un prestamista requerirá seguro contra inundaciones, y puede ser costoso. Avise al comprador y considérelo en su presupuesto.",
  "Loan exceeds pre-approval.": "El préstamo excede la pre-aprobación.",
  "The loan amount ($": "El monto del préstamo ($",
