  ". Lower the loan amount, increase the down payment, or get an updated pre-approval. You can still proceed.": ". Reduzca el monto del préstamo, aumente el pago inicial, u obtenga una pre-aprobación actualizada. Aun así puede continuar.",
  "Offer expiration is today or in the past.": "El vencimiento de la oferta es hoy o ya pasó.",
  "Pick a future date (typically 1-2 business days out) so the seller has time to respond.": "Elija una fecha futura (típicamente 1-2 días hábiles después) para que el vendedor tenga tiempo de responder.",
  "Seller contribution is over 6% of price.": "La contribución del vendedor supera el 6% del precio.",
  "Most loan programs cap seller-paid closing costs (FHA 6%, Conventional 3-9% by down payment, VA limited). $": "La mayoría de los programas de préstamo limitan los costos de cierre pagados por el vendedor (FHA 6%, Convencional 3-9% según el pago inicial, VA limitado). $",
