  "💡 New here, or training an agent?": "💡 ¿Es nuevo aquí, o está capacitando a un agente?",
  "📖 How Contacts Work — Start Here": "📖 Cómo Funcionan los Contactos — Comience Aquí",
  "🎁 What's a \"pop-by\"?": "🎁 ¿Qué es un \"pop-by\"?",
  "A pop-by is when you personally drop off a small, thoughtful gift to a top client — a pie in the fall, a cold drink in summer, a little something just to say hello. It keeps you top-of-mind so they think of you (and refer you) when real estate comes up.": "Un pop-by es cuando usted personalmente le entrega un pequeño y considerado regalo a un cliente destacado — un pastel en otoño, una bebida fría en verano, un pequeño detalle solo para saludar. Esto lo mantiene presente en su mente para que piensen en usted (y lo refieran) cuando surja un tema de bienes raíces.",
  "Turn this on and the app will remind you to pop by your A/B clients a few times a year and suggest gift ideas.": "Active esto y la aplicación le recordará visitar a sus clientes A/B unas cuantas veces al año y le sugerirá ideas de regalos.",
  "It's optional": "Es opcional",
  "— leave it off if pop-bys aren't your style.": "— déjelo desactivado si los pop-bys no son su estilo.",
  "🔍 Search name, email, phone...": "🔍 Buscar nombre, correo, teléfono...",
