  "Closing falls on a": "El cierre cae un",
  "Title and closing companies are closed on weekends — this date likely won't work. Pick a weekday, or override to keep it.": "Las compañías de títulos y cierre no abren los fines de semana — es probable que esta fecha no funcione. Elija un día entre semana, o anule para conservarla.",
  "Override — keep this date": "Anular — conservar esta fecha",
  "Green = commonly filled on most offers · plain = optional / only when it applies": "Verde = se completa comúnmente en la mayoría de las ofertas · normal = opcional / solo cuando aplica",
