  "Every term the app read from the offer is below. Edit only what changes — changed terms turn red. Everything else stays exactly as the buyer wrote it.": "Todos los términos que la aplicación leyó de la oferta están abajo. Edite solo lo que cambie — los términos modificados se muestran en rojo. Todo lo demás permanece exactamente como lo escribió el comprador.",
