  "Who signs when": "Quién firma y cuándo",
  "You send the counter. The buyer initials your changes (or resubmits). Your seller signs last — after the buyer accepts.": "Usted envía la contraoferta. El comprador inicializa sus cambios (o vuelve a presentar). Su vendedor firma al final — después de que el comprador acepte.",
