  "Edit anything you like. It asks them to strike and initial your changes or resubmit, and their reply comes back to this deal automatically. Nothing is sent until you press Send.": "Edite lo que desee. Se les pide tachar e inicializar sus cambios o volver a presentar, y su respuesta regresa a esta transacción automáticamente. No se envía nada hasta que presione Enviar.",
