  "Seller accepts": "El vendedor acepta",
  "When the seller counters your buyer's offer": "Cuando el vendedor hace contraoferta a la oferta de su comprador",
  "— tap 🔁 They countered and pick the listing agent's email (or the document, or type the changes). The app reads it against everything your buyer signed and lists every change.": "— toque 🔁 Hicieron contraoferta y elija el correo del agente de listado (o el documento, o escriba los cambios). La aplicación lo compara con todo lo que firmó su comprador y enumera cada cambio.",
  "Check it": "Revíselo",
  "— anything changed in their document that their email doesn't mention is flagged red. Tick \"I see it\" on each one, fix anything it read wrong, and save.": "— cualquier cambio en su documento que su correo no mencione se marca en rojo. Marque \"Lo veo\" en cada uno, corrija lo que se haya leído mal, y guarde.",
  "— Accept their counter (a revised offer with their changes filled in), Counter back (same, then change what your buyer wants), Buyer initials their copy (initials placed beside each change), or Buyer says no.": "— Aceptar su contraoferta (una oferta revisada con sus cambios completados), Volver a contraofertar (lo mismo, luego cambie lo que su comprador desea), El comprador inicializa su copia (iniciales colocadas junto a cada cambio), o El comprador dice que no.",
  "Buyer signs, you send it back": "El comprador firma, usted lo envía de regreso",
  "— the revised offer goes through the same steps as the first one: packet → buyer signatures → 📧 Send to listing agent.": "— la oferta revisada pasa por los mismos pasos que la primera: paquete → firmas del comprador → 📧 Enviar al agente de listado.",
  "— tap ✅ Seller accepted on the revised offer. When the executed contract comes back, upload it — the app checks it against what your buyer signed.": "— toque ✅ El vendedor aceptó en la oferta revisada. Cuando regrese el contrato ejecutado, súbalo — la aplicación lo compara con lo que firmó su comprador.",
  "Buyer signed": "El comprador firmó",
  " — waiting": " — en espera",
  "Yes, accept counter": "Sí, aceptar contraoferta",
  "Yes, counter back": "Sí, volver a contraofertar",
  "Your buyer says NO to the seller's counter. Add a note for the file (optional). This marks the offer withdrawn — tell the listing agent yourself; the app doesn't email them.": "Su comprador dice NO a la contraoferta del vendedor. Agregue una nota para el archivo (opcional). Esto marca la oferta como retirada — avísele usted mismo al agente de listado; la aplicación no le envía correo.",
  "Withdraw offer": "Retirar oferta",
  "Re-read their counter? (Use this if you picked the wrong email or document.)": "¿Volver a leer su contraoferta? (Use esto si eligió el correo o documento equivocado.)",
  "Re-read": "Volver a leer",
  "🔁 What the seller changed": "🔁 Lo que cambió el vendedor",
