  "The tool reads these standard MLS export fields. Set up a \"CMA Export\" report view in MLS with these columns:": "La herramienta lee estos campos estándar de exportación de MLS. Configure una vista de reporte \"Exportación CMA\" en MLS con estas columnas:",
