  "⭐ Condition & lot — based on Liz's in-person walkthrough": "⭐ Condición y lote — según la visita en persona de Liz",
  "These are the most important inputs for an accurate price. The comp data cannot tell us about condition or lot quality — Liz's judgment from the listing appointment does. Be honest. A home rated higher than reality will sit on the market.": "Estos son los datos más importantes para un precio preciso. Los datos de comparables no pueden indicarnos la condición o la calidad del lote — el criterio de Liz desde la cita de listado sí. Sea honesto(a). Una casa calificada más alta que la realidad se quedará estancada en el mercado.",
