  "Tip:": "Consejo:",
  "If you have photos of the kitchen, baths, flooring, and living spaces, upload them to a chat with Claude and ask \"What condition tier?\" for a second opinion before selecting.": "Si tiene fotos de la cocina, baños, pisos y áreas de estar, súbalas a un chat con Claude y pregunte \"¿Qué nivel de condición?\" para obtener una segunda opinión antes de seleccionar.",
  "Features that affect price": "Características que afectan el precio",
  "These all get factored into the recommended price using comp data where possible, Florida rules of thumb where not.": "Todas estas se consideran en el precio recomendado usando datos de comparables cuando es posible, y reglas generales de Florida cuando no lo es.",
  "Private pool (best)": "Piscina privada (lo mejor)",
