  "Golf course view": "Vista al campo de golf",
  "Is this home currently listed?": "¿Esta casa está listada actualmente?",
  "If yes, the home's actual market behavior matters more than any computed price. The tool will use this to recommend the right reduction strategy when the listing has stalled.": "Si es así, el comportamiento real de la casa en el mercado importa más que cualquier precio calculado. La herramienta usará esto para recomendar la estrategia de reducción correcta cuando el listado se haya estancado.",
  "Yes, this home is currently on the market": "Sí, esta casa está actualmente en el mercado",
  "Current List Price ($)": "Precio de lista actual ($)",
  "Days on Market": "Días en el mercado",
  "Total $ Reduced So Far": "Total $ reducido hasta ahora",
