  "Multiple offers": "Múltiples ofertas",
  "Total $ Reduced:": "Total $ reducido:",
  "Enter the dollar amount the listing has been cut since the original list price. For example, if it was listed at $659,000 and is now $614,999, enter": "Ingrese el monto en dólares que se ha recortado el listado desde el precio de lista original. Por ejemplo, si se listó en $659,000 y ahora está en $614,999, ingrese",
  ". This tells the tool how aggressively the market has already rejected this home — homes with significant prior reductions need bigger further cuts to find a buyer.": ". Esto le indica a la herramienta qué tan agresivamente el mercado ya ha rechazado esta casa — las casas con reducciones previas significativas necesitan recortes adicionales mayores para encontrar comprador.",
  "⚖ Manual price override": "⚖ Anulación manual del precio",
  "· optional": "· opcional",
  "If your judgment about this specific home tells you a different number than the tool calculated, enter your price here and it replaces the recommended tier. The tool does not always have enough information to be right — Liz's experience does. Use this freely.": "Si su criterio sobre esta casa en particular le indica un número distinto al calculado por la herramienta, ingrese su precio aquí y reemplazará el nivel recomendado. La herramienta no siempre tiene suficiente información para acertar — la experiencia de Liz sí. Úselo con libertad.",
  "Your List Price ($)": "Su precio de lista ($)",
  "Why this number?": "¿Por qué este número?",
  "optional note": "nota opcional",
  "e.g., Condition tier was understated, or pond view is uniquely valuable in this pocket": "ej., el nivel de condición estaba subestimado, o la vista al estanque es especialmente valiosa en esta zona",
  "Carrying cost": "Costo de mantenimiento",
  "Powers the Cost of Waiting calculation. Get HOA from listing, property tax from county appraiser site, insurance from HOI dec page, mortgage P&I from seller's statement.": "Alimenta el cálculo de Costo de Esperar. Obtenga el HOA del listado, el impuesto predial del sitio del tasador del condado, el seguro de la carátula de la póliza (HOI) y el capital e interés (P&I) de la hipoteca del estado de cuenta del vendedor.",
  "Monthly HOA ($)": "HOA mensual ($)",
  "Annual Property Tax ($)": "Impuesto predial anual ($)",
  "Annual Insurance ($)": "Seguro anual ($)",
  "Mortgage P&I ($/mo)": "Hipoteca P&I ($/mes)",
  "03 · COMPS": "03 · COMPARABLES",
  "Comparable properties": "Propiedades comparables",
  "Tap rows to select. Outliers (price-per-sqft >2.5× normal deviation from median) are flagged in red and automatically excluded from tier calculations even if you select them.": "Toque las filas para seleccionar. Los valores atípicos (precio por pie cuadrado >2.5× desviación normal de la mediana) se marcan en rojo y se excluyen automáticamente de los cálculos de nivel aunque los seleccione.",
  "Enter the subject's Heated Sqft in section 02 above": "Ingrese los pies cuadrados habitables del sujeto en la sección 02 arriba",
  "to run the pricing analysis. You can select comps now — the verdict and pricing tiers appear once sqft is set.": "para ejecutar el análisis de precio. Puede seleccionar comparables ahora — el veredicto y los niveles de precio aparecen una vez que se defina el tamaño en pies cuadrados.",
  "outlier comp(s) detected and auto-excluded from calculations:": "comparable(s) atípico(s) detectado(s) y excluido(s) automáticamente de los cálculos:",
