  "Upload a monthly statement (CSV export works best; PDF and screenshots also work). AI sorts each transaction into income vs expense and suggests a category. You review everything before it's saved.": "Suba un estado de cuenta mensual (la exportación CSV funciona mejor; PDF y capturas de pantalla también funcionan). La IA clasifica cada transacción en ingreso o gasto y sugiere una categoría. Usted revisa todo antes de que se guarde.",
