  "Checking / Bank": "Cuenta corriente / Banco",
  "Credit Card": "Tarjeta de crédito",
  "Statement period": "Período del estado de cuenta",
  "optional — we'll read it off the statement if left blank": "opcional — lo leeremos del estado de cuenta si lo deja en blanco",
  "— let AI read it —": "— dejar que la IA lo lea —",
  "⏳ Working...": "⏳ Trabajando...",
  "📎 Upload Statement": "📎 Subir estado de cuenta",
  "statements you've imported": "estados de cuenta que ha importado",
  "Showing your": "Mostrando sus",
  "statements (switch “Account type” above to see the other kind). Picked the wrong month? Fix it right in the": "estados de cuenta (cambie «Tipo de cuenta» arriba para ver el otro tipo). ¿Eligió el mes incorrecto? Corríjalo directamente en la",
  "column. Remove any that's wrong or a duplicate — its transactions come back out automatically.": "columna. Elimine cualquiera que esté mal o sea un duplicado — sus transacciones se eliminan automáticamente.",
  "Reconciling is automatic:": "La conciliación es automática:",
  "AI reads each statement's beginning and ending balance, and ✓ means every transaction is accounted for — you can adjust the Begin/End numbers if the statement was hard to read.": "La IA lee el saldo inicial y final de cada estado de cuenta, y ✓ significa que todas las transacciones están contabilizadas — puede ajustar los números de Inicio/Fin si el estado de cuenta era difícil de leer.",
  "statements imported yet.": "estados de cuenta importados todavía.",
