  ". They now appear in your Expenses, Income, and P&L.": ". Ahora aparecen en sus Gastos, Ingresos y P&L.",
  "Import another": "Importar otro",
  "📋 Before you hit Import — a quick 3-step review": "📋 Antes de hacer clic en Importar — una revisión rápida de 3 pasos",
  "1. Uncheck anything that isn't real income or a real business expense.": "1. Desmarque cualquier cosa que no sea un ingreso real o un gasto de negocio real.",
  "On a credit-card statement, a PAYMENT to the card is NOT income — it’s just you paying the bill. The real expenses are the charges. We already unchecked the payments we spotted (look for the ⚠️ notes) — give them a quick glance to confirm.": "En un estado de cuenta de tarjeta de crédito, un PAGO a la tarjeta NO es ingreso — es solo usted pagando la factura. Los gastos reales son los cargos. Ya desmarcamos los pagos que detectamos (busque las notas ⚠️) — échelos un vistazo rápido para confirmar.",
  "Transfers between your own accounts and credit-card bill payments are NOT income or expenses. Commission deposits from your closed deals are already counted by the app — importing them again would double-count. We unchecked what we spotted (look for the ⚠️ notes) — give them a quick glance.": "Las transferencias entre sus propias cuentas y los pagos de la factura de la tarjeta de crédito NO son ingresos ni gastos. Los depósitos de comisión de sus transacciones cerradas ya están contados por la aplicación — importarlos de nuevo los duplicaría. Desmarcamos lo que detectamos (busque las notas ⚠️) — échelos un vistazo rápido.",
  "2. Check the Type on each line": "2. Verifique el Tipo en cada línea",
  "— money in should say": "— el dinero que entra debe decir",
  ", money out should say": ", el dinero que sale debe decir",
  "Expense": "Gasto",
  "3. Check each Category.": "3. Verifique cada Categoría.",
  "The AI took its best guess — fix any that look wrong, because the category is what shows on your P&L and at tax time.": "La IA hizo su mejor estimación — corrija las que se vean mal, porque la categoría es lo que se muestra en su P&L y al momento de los impuestos.",
  "Then tap": "Luego toque",
  "✅ Import selected": "✅ Importar seleccionados",
  ". Nothing is saved until you do — and you can always remove an import later.": ". Nada se guarda hasta que lo haga — y siempre puede eliminar una importación más tarde.",
