  "stale.": "estancado.",
  "The home has been deeply rejected by the market — gentle reductions have already been tried and failed. The next cut needs to be aggressive (5%+) to find a new buyer pool.": "La casa ha sido profundamente rechazada por el mercado — ya se han intentado reducciones suaves sin éxito. El próximo recorte debe ser agresivo (5%+) para encontrar un nuevo grupo de compradores.",
  "The home has been moderately rejected — gentle 1-2% cuts will likely fail. Meaningful reductions (3-7%) are needed to reactivate buyer interest.": "La casa ha sido moderadamente rechazada — los recortes suaves de 1-2% probablemente fallen. Se necesitan reducciones significativas (3-7%) para reactivar el interés de los compradores.",
  "The home is just starting to stall. A modest reduction (2-3%) plus fresh marketing can still generate renewed activity.": "La casa apenas está comenzando a estancarse. Una reducción moderada (2-3%) junto con mercadeo renovado aún puede generar nueva actividad.",
  "The comp math says this home should sell around": "El cálculo de comparables indica que esta casa debería venderse alrededor de",
  ", but the home has been listed": ", pero la casa ha estado listada",
  "below": "por debajo de",
  "that and still hasn't sold. That's a strong signal the comp math is overestimating — there are factors the data can't capture (condition, lot, marketing, layout) that buyers can see in person.": "eso y aún no se ha vendido. Esa es una señal fuerte de que el cálculo de comparables está sobreestimando — hay factores que los datos no pueden captar (condición, lote, mercadeo, distribución) que los compradores pueden ver en persona.",
  "The comp math would have recommended": "El cálculo de comparables habría recomendado",
  ", but that's": ", pero eso está",
  "above": "por encima de",
  "the price the market has already refused. The tool is recommending reductions based on real market behavior, not just computed comp medians.": "el precio que el mercado ya ha rechazado. La herramienta está recomendando reducciones basadas en el comportamiento real del mercado, no solo en medianas calculadas de comparables.",
  "The \"Expected DOM\" below refers to days AFTER the reduction takes effect, not total days since the original listing.": "El \"DOM esperado\" abajo se refiere a los días DESPUÉS de que la reducción entre en vigencia, no al total de días desde el listado original.",
