  ". For your": ". Para su casa de",
  "sqft home, that's the foundation of our recommendation — then we adjusted for your specific features (pool, story count, garage, view) and any upgrades you've made.": "pies cuadrados, esa es la base de nuestra recomendación — luego ajustamos según sus características específicas (piscina, número de pisos, garaje, vista) y cualquier mejora que haya hecho.",
  "Market Trend": "Tendencia del Mercado",
  "The market is moving against us.": "El mercado está en nuestra contra.",
  "The market is working in our favor.": "El mercado está a nuestro favor.",
  "The market is steady right now.": "El mercado está estable en este momento.",
  "Market Direction": "Dirección del Mercado",
  "This matters more than most sellers realize.": "Esto importa más de lo que la mayoría de los vendedores se dan cuenta.",
  "Even pricing \"at market\" today means selling for less by the time the home closes — because the market keeps moving while your home sits. We've already adjusted our recommended price to where the market will": "Incluso ponerle precio \"al mercado\" hoy significa vender por menos para cuando la casa cierre — porque el mercado sigue moviéndose mientras su casa espera. Ya hemos ajustado nuestro precio recomendado a donde el mercado",
  "be": "estará",
  "when your home closes — not where it was when these comps sold.": "cuando su casa cierre — no donde estaba cuando se vendieron estos comparables.",
  "Recent sales show prices are appreciating. We've accounted for this in your recommended price — pricing slightly above the most recent closed sales because the market is moving with us.": "Las ventas recientes muestran que los precios están subiendo. Hemos tomado esto en cuenta en su precio recomendado — poniendo un precio ligeramente por encima de las ventas cerradas más recientes porque el mercado está a nuestro favor.",
  "A flat market gives us a clear read — your home is worth what comparable homes are selling for today, and that's not changing quickly.": "Un mercado estable nos da una lectura clara — su casa vale lo que las casas comparables se están vendiendo hoy, y eso no cambia rápidamente.",
  "Your Choice": "Su Elección",
  "You have three pricing options.": "Tiene tres opciones de precio.",
  "Many sellers think pricing high is a \"free test.\" The data tells a different story. Here's the honest breakdown:": "Muchos vendedores piensan que poner un precio alto es una \"prueba gratis\". Los datos cuentan una historia diferente. Aquí está el desglose honesto:",
