  "— often more than any premium from the higher list price.": "— a menudo más que cualquier prima del precio de lista más alto.",
  "Our Honest Advice": "Nuestro Consejo Honesto",
  "List at": "Liste en",
  "This price respects what your home is genuinely worth, positions you to sell in a reasonable timeframe, and gives you the best chance of": "Este precio respeta lo que su casa realmente vale, lo posiciona para vender en un plazo razonable, y le da la mejor oportunidad de",
  "netting the most money": "obtener la mayor ganancia neta",
  "after accounting for carrying costs and avoided price reductions.": "después de considerar los costos de mantenimiento y las reducciones de precio evitadas.",
  "Homes priced right from day one sell faster, attract stronger offers, and net more money than homes that start high and chase the market down.": "Las casas con el precio correcto desde el primer día se venden más rápido, atraen ofertas más fuertes y generan más dinero neto que las casas que empiezan altas y luego persiguen al mercado hacia abajo.",
  "One more thing.": "Una cosa más.",
  "The market is softening right now. Pricing correctly today is more important than ever — every month of delay costs you twice: in carrying costs, and in the market moving away from your price.": "El mercado se está suavizando en este momento. Poner el precio correcto hoy es más importante que nunca — cada mes de retraso le cuesta el doble: en costos de mantenimiento, y en que el mercado se aleje de su precio.",
  "We've put real care into this analysis. If you have questions about the comps, the math, or our marketing plan, we'd love to walk you through it in person.": "Hemos puesto verdadero cuidado en este análisis. Si tiene preguntas sobre los comparables, los cálculos, o nuestro plan de mercadeo, nos encantaría explicárselo en persona.",
