  "✓ Link generated. Expires": "✓ Enlace generado. Caduca",
  "Paste this link into chat, email, or a text message. The recipient does not need a TransactPro account.": "Pegue este enlace en un chat, correo o mensaje de texto. El destinatario no necesita una cuenta de TransactPro.",
