  "✨ Upload Broker Synopses (AI extracts comps)": "✨ Subir resúmenes del corredor (la IA extrae comparables)",
  "Upload up to 6 MLS broker synopses, PDFs, or property screenshots. AI auto-fills the comp slots — you review and tweak.": "Suba hasta 6 resúmenes de corredor de MLS, PDFs o capturas de pantalla de propiedades. La IA completa automáticamente los espacios de comparables — usted revisa y ajusta.",
  "Subject property:": "Propiedad sujeto:",
  "The home you're pricing. Enter specs first, then check off any upgrades. The system uses these to adjust each comp.": "La propiedad que está tasando. Ingrese las especificaciones primero, luego marque las mejoras. El sistema las usa para ajustar cada comparable.",
