  "FL Upgrades / Features": "Mejoras / Características de FL",
  "Check anything the subject property has. Dollar values are FL market averages — you can override on individual comps.": "Marque todo lo que tenga la propiedad sujeto. Los valores en dólares son promedios del mercado de FL — puede anularlos en comparables individuales.",
  "Custom Upgrades": "Mejoras personalizadas",
  "Anything not in the standard list. Examples: tankless water heater, generator, smart home wiring, high-end appliances.": "Cualquier cosa que no esté en la lista estándar. Ejemplos: calentador de agua sin tanque, generador, cableado de casa inteligente, electrodomésticos de alta gama.",
  "$ adjustment": "Ajuste en $",
  "+ Add Custom Upgrade": "+ Agregar mejora personalizada",
