  "Adjusted Value:": "Valor ajustado:",
  "Open this calculator from inside a transaction to generate a compliance PDF.": "Abra esta calculadora desde dentro de una transacción para generar un PDF de cumplimiento.",
  "Quick CMA": "CMA rápido",
  "Comparative Market Analysis. Enter subject property + 3-6 comps. App computes adjusted values and suggests a list price.": "Análisis Comparativo de Mercado. Ingrese la propiedad sujeto + 3-6 comparables. La app calcula los valores ajustados y sugiere un precio de lista.",
  "🏠 Subject Property": "🏠 Propiedad sujeto",
  "📈 Suggested Price": "📈 Precio sugerido",
  "✨ AI Comp Extraction": "✨ Extracción de comparables con IA",
  "No comps extracted. Try clearer files.": "No se extrajeron comparables. Intente con archivos más claros.",
  "✅ Extracted ": "✅ Se extrajo ",
  " comp": " comparable",
  ". Review each one — fields can be adjusted before generating the report.": ". Revise cada uno — los campos se pueden ajustar antes de generar el informe.",
  "Or enter manually:": "O ingrese manualmente:",
  "3-6 recently sold homes (within last 6 months, ½ mile, similar specs). The system auto-adjusts for differences from your subject.": "3-6 casas vendidas recientemente (dentro de los últimos 6 meses, a ½ milla, especificaciones similares). El sistema ajusta automáticamente las diferencias con su propiedad sujeto.",
  "+ Add Comp (": "+ Agregar comparable (",
  "more allowed)": "más permitidos)",
  "Add at least one comp with sold price + sqft to see suggested pricing.": "Agregue al menos un comparable con precio de venta + pies cuadrados para ver el precio sugerido.",
