  "\"Keep a copy of forwarded messages\"": "\"Mantener una copia de los mensajes reenviados\"",
  ". No confirmation needed. (Outlook may first ask you to verify your own account with a code — that's Microsoft, one time.)": ". No se necesita confirmación. (Outlook puede pedirle primero verificar su propia cuenta con un código — eso es de Microsoft, una sola vez.)",
  "Work (Microsoft 365) email and it says forwarding is blocked? Ask whoever manages your company email to allow automatic forwarding.": "¿Correo de trabajo (Microsoft 365) y dice que el reenvío está bloqueado? Pídale a quien administra el correo de su empresa que permita el reenvío automático.",
