  "doesn't allow automatic forwarding.": "no permite el reenvío automático.",
  "Two options:": "Dos opciones:",
  "Use a Gmail or Outlook address for your deals (change your login email in Team settings, or ask your admin), then come back here,": "Use una dirección de Gmail u Outlook para sus transacciones (cambie su correo de inicio de sesión en Configuración del equipo, o pídaselo a su administrador), luego regrese aquí,",
  "With": "Con",
