  "Forward deal emails by hand to": "Reenvíe manualmente los correos de la transacción a",
  "— the app files them.": "— la aplicación los archiva.",
  "In your email's settings, look for": "En la configuración de su correo, busque",
  "(sometimes under \"Mail\", \"Rules\" or \"Accounts\").": "(a veces bajo \"Correo\", \"Reglas\" o \"Cuentas\").",
  "Forward all incoming mail to": "Reenvíe todo el correo entrante a",
  "and choose to": "y elija",
  "keep a copy": "mantener una copia",
  "in your inbox → Save. If it sends a confirmation, it shows up on this page — click it.": "en su bandeja de entrada → Guardar. Si envía una confirmación, aparece en esta página — haga clic en ella.",
  "below. Stuck? Ask whoever manages your email, or send your admin a screenshot of the settings page.": "abajo. ¿Atascado? Pídale a quien administra su correo, o envíele a su administrador una captura de pantalla de la página de configuración.",
  "📥 Catch deal emails sent to your inbox": "📥 Capturar correos de transacciones enviados a su bandeja de entrada",
  "Title companies, lenders and other agents often email": "Las compañías de títulos, prestamistas y otros agentes a menudo escriben",
  "directly. Forward your inbox to your personal TransactPro address once, and emails whose": "directamente. Reenvíe su bandeja de entrada a su dirección personal de TransactPro una vez, y los correos cuyo",
  "subject mentions one of your deals": "asunto mencione una de sus transacciones",
