  "📨 Send me a test email": "📨 Enviarme un correo de prueba",
  "↻ Check status": "↻ Verificar estado",
  "Referral fee off the top": "Comisión de referido desde el inicio",
  "Co-agent split": "División con el coagente",
  "Brokerage split": "División con la correduría",
