  "Mark {n} vendor paid under contractor categories (cleaning, TC, referral fees, etc.) as 1099? You can uncheck any afterward.": "¿Marcar {n} proveedor pagado bajo categorías de contratista (limpieza, TC, comisiones por referido, etc.) como 1099? Puede desmarcarlo después.",
  "Mark {n} vendors paid under contractor categories (cleaning, TC, referral fees, etc.) as 1099? You can uncheck any afterward.": "¿Marcar {n} proveedores pagados bajo categorías de contratista (limpieza, TC, comisiones por referido, etc.) como 1099? Puede desmarcarlos después.",
  "No vendors for {year}.": "No hay proveedores para {year}.",
  "No contractor-category expenses for {year}. Categorize expenses as Contract Labor (1099), Referral Fees, Office Cleaning, etc. — or check “Show every vendor.”": "No hay gastos de categoría de contratista para {year}. Clasifique los gastos como Mano de Obra Contratada (1099), Comisiones por Referido, Limpieza de Oficina, etc. — o marque “Mostrar todos los proveedores.”",
  "W-9 info — {name}": "Información del W-9 — {name}",
  "These transactions add up to an ending balance of {amount}, but you entered {amount2}. A line may be missing or miscategorized.": "Estas transacciones suman un saldo final de {amount}, pero usted ingresó {amount2}. Puede faltar una línea o estar mal clasificada.",
  "Remove \"{label}\"?\n\nThis takes its {v2} saved transaction(s) back out of your Expenses, Income, and P&L. You can re-import the statement later if needed.": "¿Eliminar \"{label}\"?\n\nEsto retira sus {v2} transacción(es) guardada(s) de Gastos, Ingresos y P&L. Puede volver a importar el estado de cuenta más tarde si lo necesita.",
  "Removed {v1} expense and {v2} income item(s).": "Se eliminaron {v1} gasto(s) y {v2} ingreso(s).",
  "{message}\n\nImport it anyway?": "{message}\n\n¿Importar de todos modos?",
  "✅ Import {n} selected": "✅ Importar {n} seleccionado(s)",
  "📋 \"{name}\"\n\nThis form is a placeholder. An admin must upload the licensed PDF before agents can download or share it.": "📋 \"{name}\"\n\nEste formulario es un marcador de posición. Un administrador debe subir el PDF con licencia antes de que los agentes puedan descargarlo o compartirlo.",
