  "Delete the {date} tour day and its {n} home(s)? Scorecards on those homes are deleted too.": "¿Eliminar el día de recorrido {date} y sus {n} propiedad(es)? Las tarjetas de puntuación de esas propiedades también se eliminarán.",
  "Delete the {date} tour day?": "¿Eliminar el día de recorrido {date}?",
  "Remove {address} from this tour?": "¿Quitar {address} de este recorrido?",
  "{address} was added before the app read contract details from the MLS report (or was typed in by hand), so it doesn't have the seller, parcel ID, county, legal description, HOA or title company yet.\n\nOK = upload its Broker Full report once — the app fills this offer from it.\nCancel = start the offer with the basics only.": "{address} se agregó antes de que la aplicación leyera los detalles del contrato del informe de MLS (o se escribió a mano), por lo que aún no tiene el vendedor, ID de parcela, condado, descripción legal, HOA ni compañía de títulos.\n\nAceptar = suba su informe Broker Full una vez — la aplicación completará esta oferta a partir de él.\nCancelar = comenzar la oferta solo con lo básico.",
