  "Uploading {done}/{total}...": "Subiendo {done}/{total}...",
  "📋 \"{name}\" is a placeholder.\n\nAn admin must upload the licensed PDF before this form can be downloaded. Open Settings → Forms Library to upload.": "📋 \"{name}\" es un marcador de posición.\n\nUn administrador debe subir el PDF con licencia antes de que este formulario pueda descargarse. Abra Configuración → Biblioteca de Formularios para subirlo.",
  "{v1} property": "Propiedad de {v1}",
  "{overdue} overdue item(s)": "{overdue} artículo(s) vencido(s)",
  "Hi, this is The Liz Team Realty.\n\nThis is a reminder that the following task is {urgency}:\n\n📋 {name}\n📍 {address}, {city}, FL\n📅 Due: {date}\n\nPlease take action as soon as possible. Thank you!": "Hola, le saluda The Liz Team Realty.\n\nEste es un recordatorio de que la siguiente tarea está {urgency}:\n\n📋 {name}\n📍 {address}, {city}, FL\n📅 Vence: {date}\n\nPor favor tome acción lo antes posible. ¡Gracias!",
