  "Stop the automated follow-up for \"{label}\" to {v2}?\n\nNo more reminder emails or texts will be sent for it.": "¿Detener el seguimiento automático de \"{label}\" para {v2}?\n\nNo se enviarán más correos ni textos de recordatorio para esto.",
