  "Reset the portal PIN for {name}?\n\nTheir old PIN stops working immediately. The next time they open their portal link, they'll be asked to create a new PIN.": "¿Restablecer el PIN del portal de {name}?\n\nSu antiguo PIN dejará de funcionar de inmediato. La próxima vez que abra el enlace de su portal, se le pedirá crear un nuevo PIN.",
  "✅ PIN cleared for {name}. Tell them to open their portal link again — it will ask them to CREATE a new 4-digit PIN.": "✅ PIN eliminado para {name}. Dígale que abra el enlace de su portal de nuevo — se le pedirá CREAR un nuevo PIN de 4 dígitos.",
