  "📨 Will reach {n} contact ({audienceLabel}, after skipping opt-outs and contacts with no email).": "📨 Llegará a {n} contacto ({audienceLabel}, después de omitir los que optaron por no recibir y contactos sin correo).",
  "📨 Will reach {n} contacts ({audienceLabel}, after skipping opt-outs and contacts with no email).": "📨 Llegará a {n} contactos ({audienceLabel}, después de omitir los que optaron por no recibir y contactos sin correo).",
