  "Manage the workflow tasks that get auto-generated for each transaction type. Changes apply to new transactions going forward.": "Administre las tareas de flujo de trabajo que se generan automáticamente para cada tipo de transacción. Los cambios se aplican a las nuevas transacciones en adelante.",
