  "Start in the simple \"Money\" view — add an expense or import a bank statement.": "Comience en la vista simple de \"Dinero\" — agregue un gasto o importe un estado de cuenta bancario.",
  "Closed-deal commission flows in on its own; flip to the Advanced view only if you want full accounting.": "La comisión de una transacción cerrada entra sola; cambie a la vista Avanzada solo si desea contabilidad completa.",
  "Drop in a contract you're already working on and watch the app read it and build the timeline — or start one from scratch in three steps.": "Suba un contrato en el que ya esté trabajando y vea cómo la aplicación lo lee y crea la cronología — o inicie uno desde cero en tres pasos.",
