  "For": "Para",
  "Hi! 👋 I'm your support assistant. Ask me anything about how to use the app — like \"How do I receive an offer?\" or \"Where do I set my goals?\"": "¡Hola! 👋 Soy su asistente de soporte. Pregúnteme lo que quiera sobre cómo usar la app — como \"¿Cómo recibo una oferta?\" o \"¿Dónde configuro mis metas?\"",
  "Try asking…": "Intente preguntar…",
  "How do I start a new transaction?": "¿Cómo inicio una nueva transacción?",
  "How do I receive an offer?": "¿Cómo recibo una oferta?",
  "Where do I set up my goals?": "¿Dónde configuro mis metas?",
  "How do Pop-Bys work?": "¿Cómo funcionan los Pop-Bys?",
  "Type your question…": "Escriba su pregunta…",
  "AI answers can occasionally be off. For a bug or account issue, use the 📣 Feedback tab; for anything urgent on a live deal, call or text your broker.": "Las respuestas de la IA a veces pueden ser incorrectas. Para un error o problema de cuenta, use la pestaña 📣 Comentarios; para algo urgente en una transacción activa, llame o envíe un mensaje de texto a su corredor.",
  "Thank you — we got it!": "¡Gracias — lo recibimos!",
  "Your note went straight to the team. We read every single one, and it helps us make the app better for you.": "Su nota llegó directo al equipo. Leemos cada una, y nos ayuda a mejorar la app para usted.",
  "Send another": "Enviar otro",
  "Found a bug? Have an idea? Need a hand? Tell us — it goes straight to our team.": "¿Encontró un error? ¿Tiene una idea? ¿Necesita ayuda? Cuéntenos — llega directo a nuestro equipo.",
  "What kind of feedback is this?": "¿Qué tipo de comentario es este?",
  "🐞 Something’s broken": "🐞 Algo está fallando",
  "💡 Idea / request": "💡 Idea / solicitud",
  "🆘 Need help": "🆘 Necesito ayuda",
  "💬 Other": "💬 Otro",
  "What happened? What were you trying to do, and what went wrong? The more detail, the faster we can fix it.": "¿Qué pasó? ¿Qué estaba tratando de hacer y qué salió mal? Cuanto más detalle, más rápido podemos solucionarlo.",
  "What would you like to see? Describe the idea or the change you’re hoping for.": "¿Qué le gustaría ver? Describa la idea o el cambio que espera.",
  "How can we help? Describe your question or the problem you’re running into and our support team will get back to you.": "¿Cómo podemos ayudar? Describa su pregunta o el problema que está teniendo y nuestro equipo de soporte le responderá.",
  "Tell us what’s on your mind.": "Cuéntenos qué tiene en mente.",
  "Send to support": "Enviar a soporte",
  "Send to the team": "Enviar al equipo",
  "We’ll know who sent it so we can follow up if needed. For an urgent issue with a live deal, call or text your contact directly.": "Sabremos quién lo envió para poder hacer seguimiento si es necesario. Para un problema urgente con una transacción activa, llame o envíe un mensaje de texto directamente a su contacto.",
  "These guides are educational only and not legal advice. For legal or tax questions, consult a real estate attorney or CPA.": "Estas guías son solo educativas y no constituyen asesoría legal. Para preguntas legales o fiscales, consulte a un abogado de bienes raíces o a un contador público (CPA).",
