  "Start a new transaction": "Iniciar una nueva transacción",
  "Click the red \"+ New Transaction\" button at the top of your dashboard.": "Haga clic en el botón rojo \"+ Nueva Transacción\" en la parte superior de su panel.",
  "Fill in the property address, the type (listing or buyer), and the key dates.": "Complete la dirección de la propiedad, el tipo (listado o comprador) y las fechas clave.",
  "Hit Save — your timeline, checklist, and reminders build themselves automatically.": "Presione Guardar — su cronología, lista de verificación y recordatorios se crean automáticamente.",
  "Add a contact": "Agregar un contacto",
  "Click \"📇 Contacts\" in the top bar.": "Haga clic en \"📇 Contactos\" en la barra superior.",
  "Tap \"+ Add Contact\" and enter their name, email, and phone.": "Toque \"+ Agregar Contacto\" e ingrese su nombre, correo y teléfono.",
  "Save — they're now available everywhere you send emails or share documents.": "Guarde — ahora estarán disponibles en todos los lugares donde envíe correos o comparta documentos.",
  "Work your \"Win the Day\" list": "Trabaje su lista de \"Gane el día\"",
  "Click the \"Win the Day\" button in the top bar.": "Haga clic en el botón \"Gane el día\" en la barra superior.",
  "Each card is one thing to do today — a reminder, a nudge, or a follow-up.": "Cada tarjeta es algo por hacer hoy — un recordatorio, un impulso o un seguimiento.",
  "Do it, then tap the card to mark it done or \"Not Today\" to push it.": "Hágalo, luego toque la tarjeta para marcarla como hecha o \"No Hoy\" para posponerla.",
  "See everything for one deal": "Vea todo sobre una transacción",
  "On the dashboard, click any transaction card.": "En el panel, haga clic en cualquier tarjeta de transacción.",
  "Use the tabs (Overview, Timeline, Documents, Parties, Messages) to move around.": "Use las pestañas (Resumen, Cronología, Documentos, Partes, Mensajes) para navegar.",
  "The Timeline tab is your step-by-step checklist for that deal.": "La pestaña Cronología es su lista de verificación paso a paso para esa transacción.",
  "Get ALL deal emails into the app (even ones sent to your personal inbox)": "Reciba TODOS los correos de la transacción en la app (incluso los enviados a su bandeja personal)",
  "Every email the app sends already carries the deal's tracked address — when anyone hits Reply or Reply All, their message files itself to the deal automatically. No setup needed.": "Cada correo que envía la app ya lleva la dirección rastreada de la transacción — cuando alguien responde o responde a todos, su mensaje se archiva automáticamente en la transacción. No requiere configuración.",
  "Each deal also has its own email address: open the deal → Messages → Replies and copy it from the green box. Give it to the title company, lender, or the other agent — anything they send to it lands on that deal.": "Cada transacción también tiene su propia dirección de correo: abra la transacción → Mensajes → Respuestas y cópiela del recuadro verde. Entréguesela a la compañía de títulos, al prestamista o al otro agente — todo lo que le envíen llegará a esa transacción.",
  "For emails people send straight to YOUR inbox: go to ⚙️ Menu → 👤 My Profile → \"Catch deal emails sent to your personal inbox\" and follow the one-time Gmail/Outlook forwarding steps.": "Para correos que las personas envían directamente a SU bandeja: vaya a ⚙️ Menú → 👤 Mi Perfil → \"Capturar correos de transacciones enviados a su bandeja personal\" y siga los pasos únicos de reenvío de Gmail/Outlook.",
  "Anything the app can't place automatically shows up on Win the Day under \"📥 Mail to file\" — file it to the right deal in one tap.": "Todo lo que la app no pueda ubicar automáticamente aparece en Gane el día bajo \"📥 Correo por archivar\" — archívelo en la transacción correcta con un solo toque.",
  "Documents & offers": "Documentos y ofertas",
  "Share a document with a client": "Compartir un documento con un cliente",
  "Open a transaction and go to the \"Documents\" tab.": "Abra una transacción y vaya a la pestaña \"Documentos\".",
  "Find the document, then click the \"📤 Share\" button next to it.": "Encuentre el documento, luego haga clic en el botón \"📤 Compartir\" junto a él.",
  "Pick who gets it (or type any email) and send — it goes out in your name.": "Elija quién lo recibe (o escriba cualquier correo) y envíe — saldrá en su nombre.",
  "Receive an offer on your listing": "Recibir una oferta en su listado",
  "Open one of your Active listings.": "Abra uno de sus listados Activos.",
  "Click \"📥 Receive Offer\" and upload the offer — it parks as a pending offer (no emails go out yet).": "Haga clic en \"📥 Recibir Oferta\" y suba la oferta — quedará como oferta pendiente (aún no se envían correos).",
  "Review your pending offers, then approve the one your seller accepts.": "Revise sus ofertas pendientes, luego apruebe la que acepte su vendedor.",
  "Send your forms (FAR/BAR, disclosures…)": "Envíe sus formularios (FAR/BAR, divulgaciones…)",
  "Open ⚙️ Menu → \"📋 Forms Library\" (or the Forms tab inside a deal).": "Abra ⚙️ Menú → \"📋 Biblioteca de Formularios\" (o la pestaña Formularios dentro de una transacción).",
  "Pick the form you need and fill it in.": "Elija el formulario que necesita y complételo.",
  "Save or send it straight to your client.": "Guárdelo o envíelo directamente a su cliente.",
  "Grow your business": "Haga crecer su negocio",
