  "Go to the CMA tab and enter the subject property + comps.": "Vaya a la pestaña CMA e ingrese la propiedad en cuestión + los comparables.",
  "Generate the report, then print or email the Seller version.": "Genere el informe, luego imprima o envíe por correo la versión del Vendedor.",
  "Send Pop-By gifts": "Enviar regalos Pop-By",
  "Click \"🎁 Pop-Bys\" in the top bar.": "Haga clic en \"🎁 Pop-Bys\" en la barra superior.",
  "Pick the contacts you want to visit — the app suggests a gift and a note for each.": "Elija los contactos que desea visitar — la app sugiere un regalo y una nota para cada uno.",
  "Use the map route to plan your run, then mark each one delivered.": "Use la ruta del mapa para planear su recorrido, luego marque cada uno como entregado.",
  "Invite a new buyer or seller (intake)": "Invitar a un nuevo comprador o vendedor (admisión)",
