  "Open the app each morning → Win the Day": "Abra la aplicación cada mañana → Gane el día",
  "Your dashboard shows exactly who to call today, why, and any birthdays or anniversaries this week. You don't have to remember anyone — the app remembers for you.": "Su panel muestra exactamente a quién llamar hoy, por qué, y los cumpleaños o aniversarios de esta semana. No tiene que recordar a nadie — la aplicación lo recuerda por usted.",
  "Make the call": "Haga la llamada",
  "Tap the green 📞 Log Call button next to the person. Their notes and reason for calling are right there so you know what to say.": "Toque el botón verde 📞 Registrar Llamada junto a la persona. Sus notas y el motivo de la llamada están allí mismo para que sepa qué decir.",
  "Log what happened": "Registre lo que ocurrió",
  "After the call, pick the outcome (Reached, Left Voicemail, etc.), type a quick 'reason for next call' (like \"follow up on pre-approval\"), and the app automatically schedules the next call for you.": "Después de la llamada, elija el resultado (Contactado, Mensaje de voz, etc.), escriba un breve 'motivo para la próxima llamada' (como \"dar seguimiento a la preaprobación\"), y la aplicación programa automáticamente la próxima llamada por usted.",
  "That's the whole loop": "Ese es todo el ciclo",
  "Call → log it → the app picks the next date → it shows up again on the right day. Hot leads come back fast, sphere & past clients come back on a relaxed schedule. You just work the list.": "Llame → regístrelo → la aplicación elige la próxima fecha → vuelve a aparecer el día indicado. Los prospectos calientes regresan rápido, la esfera y los clientes pasados regresan con un calendario relajado. Usted solo trabaja la lista.",
