  "Enter the closing date/time/location & amount the title company or attorney gave you. You'll review & edit the email before it's sent — to your side only.": "Ingrese la fecha/hora/lugar del cierre y el monto que le dio la compañía de títulos o el abogado. Usted revisará y editará el correo antes de enviarlo — solo a su parte.",
  "Waiving a required document is the agent's decision. Mark the milestone done if you have what you need, or ask the agent to waive it.": "Eximir un documento requerido es decisión del agente. Marque el paso como completo si ya tiene lo que necesita, o pídale al agente que lo exima.",
