  "Why it matters:": "Por qué importa:",
  "Your broker and compliance team can see every waiver. If audited, you must be able to defend this decision. A permanent audit-log entry is created with your name, the reason, and your justification.": "Su corredor y el equipo de cumplimiento pueden ver todas las exenciones. En caso de auditoría, usted debe poder justificar esta decisión. Se crea un registro de auditoría permanente con su nombre, el motivo y su justificación.",
