  "👥 My Team": "👥 Mi Equipo",
  "Add assistants who work under you. You can reassign any deal to a teammate from the deal's People tab — they'll see and work just that deal.": "Agregue asistentes que trabajan bajo su supervisión. Puede reasignar cualquier transacción a un compañero de equipo desde la pestaña Personas de la transacción — ellos verán y trabajarán solo esa transacción.",
  "You're a team member. Your lead coordinator assigns deals to you; they show up on your dashboard.": "Usted es miembro de un equipo. Su coordinador(a) principal le asigna transacciones; estas aparecen en su panel.",
