  "⚠️ Couldn't re-check your pre-contract steps just now — the deal itself reset fine. If listing work you already finished (sign, lockbox, photos) shows up as to-do again, open": "⚠️ No se pudieron reverificar sus pasos previos al contrato en este momento — la transacción en sí se reinició bien. Si un trabajo del listado que ya había terminado (letrero, caja de seguridad, fotos) aparece de nuevo como pendiente, abra",
