  "Click around all you like: nobody on it has an email address or a phone number, so nothing here can send a message to anyone. It disappears on its own once you add a real deal.": "Haga clic libremente: nadie en ella tiene correo electrónico ni número de teléfono, así que nada aquí puede enviarle un mensaje a nadie. Desaparece sola en cuanto agregue una transacción real.",
  "Delete the sample deal?\n\nIt's only a demo — you can create it again any time from Win The Day.": "¿Eliminar la transacción de muestra?\n\nSolo es una demostración — puede crearla de nuevo en cualquier momento desde Gane el día.",
