  "Mark this lead as Not Pursuing? It will be set to Cancelled and removed from your active list (you can reactivate it later). Type CANCEL to confirm.": "¿Marcar este prospecto como No se está gestionando? Se establecerá como Cancelado y se quitará de su lista activa (puede reactivarlo después). Escriba CANCEL para confirmar.",
