  "🧾 Sent history": "🧾 Historial de envíos",
  "The deal's group chat, with everyone on the deal: you, the agent/coordinator, and any parties like the photographer, title, and lender.": "El chat grupal de la transacción, con todos los involucrados: usted, el agente/coordinador y cualquier parte como el fotógrafo, el título y el prestamista.",
  "Replies the clients sent back — approve any milestone updates.": "Respuestas que enviaron los clientes — apruebe cualquier actualización de paso.",
  "Send the client an email/text update in the agent's voice.": "Envíele al cliente una actualización por correo o texto con la voz del agente.",
  "Send an email or text to an individual or a group.": "Envíe un correo o texto a una persona o a un grupo.",
  "Every email and text this deal has sent — welcome emails, reminders, updates — newest first.": "Todos los correos y textos que ha enviado esta transacción — correos de bienvenida, recordatorios, actualizaciones — del más reciente al más antiguo.",
  "🎓 Why this matters:": "🎓 Por qué esto importa:",
  "Use this with your buyer to set realistic expectations on price, monthly payment, and cash-to-close BEFORE writing offers. Florida's doc stamps, intangible tax, and insurance costs surprise most first-time buyers.": "Úselo con su comprador para fijar expectativas realistas sobre el precio, el pago mensual y el efectivo necesario al cierre ANTES de redactar ofertas. Los sellos documentales, el impuesto intangible y los costos de seguro de Florida sorprenden a la mayoría de los compradores primerizos.",
  "Give your buyer a clear estimate of the cash they'll need at closing, then generate a branded English or Spanish net sheet and save it to Documents.": "Dele a su comprador una estimación clara del efectivo que necesitará al cierre, luego genere una hoja neta personalizada en inglés o español y guárdela en Documentos.",
  "Sellers want to know what they'll walk away with. Use this BEFORE the listing appointment to set realistic expectations on commission, FL doc stamps (~0.7%), title fees, and mortgage payoff. Avoids \"I thought I was getting more\" at closing.": "Los vendedores quieren saber con cuánto se quedarán. Úselo ANTES de la cita de listado para fijar expectativas realistas sobre la comisión, los sellos documentales de FL (~0.7%), los costos de título y el saldo de la hipoteca. Evita el \"pensé que recibiría más\" al cierre.",
  "Transaction Activity Log": "Registro de actividad de la transacción",
