  "Add your brokerage name, logo, and branding — it displays on everything your clients see.": "Agregue el nombre, logo e identidad de su correduría — se muestra en todo lo que ven sus clientes.",
  "⚙️ Menu → ⚙️ Company Settings": "⚙️ Menú → ⚙️ Configuración de la empresa",
  "Set up your profile": "Configure su perfil",
  "Add your photo and contact info — used on every email signature and form you send.": "Agregue su foto e información de contacto — se usa en cada firma de correo y formulario que envíe.",
  "⚙️ Menu → 👤 My Profile": "⚙️ Menú → 👤 Mi perfil",
  "Add your first deal": "Agregue su primera transacción",
  "Drop in a contract you're already working on and watch the app read it and build the whole timeline — or start one from scratch in three steps. This is the part that makes everything else turn on.": "Suba un contrato en el que ya esté trabajando y observe cómo la app lo lee y arma toda la cronología — o comience uno desde cero en tres pasos. Esta es la parte que activa todo lo demás.",
  "➕ New Deal up top": "➕ Nueva transacción arriba",
  "Automatically capture deal emails": "Capture automáticamente los correos de la transacción",
  "Set up email forwarding so that messages from title companies and lenders sent to your regular inbox automatically flow into the correct deal — without the need to manually add them to the app.": "Configure el reenvío de correos para que los mensajes de compañías de títulos y prestamistas enviados a su bandeja habitual fluyan automáticamente a la transacción correcta — sin necesidad de agregarlos manualmente a la app.",
  "⚙️ Menu → 👤 My Profile → 📥 Catch deal emails": "⚙️ Menú → 👤 Mi perfil → 📥 Capturar correos de transacción",
  "Set up your goals": "Configure sus metas",
  "Tell the app what you want to earn this year and it works backwards to the calls you need to make each day.": "Indique a la app cuánto desea ganar este año y ella calculará las llamadas que debe hacer cada día.",
  "🧰 Tools → 🎯 Growth Plan": "🧰 Herramientas → 🎯 Plan de crecimiento",
  "Take the 60-second tour": "Haga el recorrido de 60 segundos",
