  " already has a portal account — we just re-sent their one-tap login link by email.\n\nIf they still don't see it (check spam), use the 🔗 Login Link button to copy the link and text it to them directly.": " ya tiene una cuenta de portal — acabamos de reenviar su enlace de acceso de un toque por correo.\n\nSi aún no lo ve (revise spam), use el botón 🔗 Enlace de acceso para copiar el enlace y enviárselo por mensaje de texto directamente.",
  "Invitation sent to ": "Invitación enviada a ",
  "! They'll get an email with a one-tap link to their portal (they set a 4-digit PIN on first use).": "! Recibirán un correo con un enlace de acceso de un toque a su portal (configuran un PIN de 4 dígitos en el primer uso).",
  " is already registered — we re-sent their login link by email. If it doesn't arrive, use 🔗 Login Link to share it directly.": " ya está registrado(a) — reenviamos su enlace de acceso por correo. Si no llega, use 🔗 Enlace de acceso para compartirlo directamente.",
