  "Could not create login link: ": "No se pudo crear el enlace de acceso: ",
  "Couldn't open that transaction — it may have been moved or you no longer have access. Try refreshing.": "No se pudo abrir esa transacción — es posible que haya sido movida o que ya no tenga acceso. Intente actualizar.",
