  "This screen fills itself once you have a deal — every deadline, call, and document that needs you, in the order it needs you. Start it either way:": "Esta pantalla se completa sola una vez que tiene una transacción — cada plazo, llamada y documento que requiere su atención, en el orden que lo necesita. Comience de cualquier forma:",
  "Upload a signed contract": "Subir un contrato firmado",
  "Drop in a deal you're already working. The app reads the price, the dates, the deposits and everyone's contact info, then builds the timeline for you.": "Agregue una transacción en la que ya está trabajando. La app lee el precio, las fechas, los depósitos y la información de contacto de todos, y luego arma la cronología por usted.",
  "Upload a contract →": "Subir un contrato →",
  "Fastest way to see what this thing does.": "La forma más rápida de ver qué hace esta herramienta.",
  "Start a deal from scratch": "Iniciar una transacción desde cero",
  "Three quick steps — the address, your client, the price. A new listing or a buyer you just signed. The checklist builds itself.": "Tres pasos rápidos — la dirección, su cliente, el precio. Un nuevo listado o un comprador que acaba de firmar. La lista de verificación se arma sola.",
