  "tells you exactly which documents this deal still needs. ②": "le indica exactamente qué documentos aún necesita esta transacción. ②",
  "Upload": "Suba",
  "straight into a checklist slot (or use the general upload). ③ Need it signed?": "directamente a una ranura de la lista de verificación (o use la carga general). ③ ¿Necesita que se firme?",
  "✍️ Get signature": "✍️ Obtener firma",
  "emails a private signing link and files the signed copy back here by itself.": "envía por correo un enlace de firma privado y archiva la copia firmada aquí automáticamente.",
  "This usually means it's an unsigned offer, or the contract dates (executed date, closing date) aren't filled in yet. ": "Esto generalmente significa que es una oferta sin firmar, o que las fechas del contrato (fecha de ejecución, fecha de cierre) aún no se han completado. ",
