  "📦 Listing Package — step 1 of every listing": "📦 Paquete de Listado — paso 1 de todo listado",
  "Package generated — watch the ⏳/✅ badges below for signing progress. The listing unlocks automatically when everything is signed.": "Paquete generado — observe las insignias ⏳/✅ a continuación para ver el progreso de la firma. El listado se desbloquea automáticamente cuando todo esté firmado.",
  "Fills the official Florida forms (listing agreement, disclosures, riders) with this deal's details and sends them to your seller to e-sign in one round. Photos, sign, and MLS stay locked until it's signed.": "Completa los formularios oficiales de Florida (contrato de listado, divulgaciones, anexos) con los datos de esta transacción y los envía a su vendedor para firma electrónica en una sola ronda. Las fotos, el letrero y el MLS permanecen bloqueados hasta que se firme.",
  "Regenerate / Resend": "Regenerar / Reenviar",
  "Prepare & Send Package": "Preparar y Enviar Paquete",
  "🏠 Buyer declining a home inspection?": "🏠 ¿El comprador rechaza la inspección de la vivienda?",
  "Generate a Home Inspection Waiver — it records that you recommended an inspection and the buyer chose to decline, which protects you. Then click": "Genere una Renuncia de Inspección de Vivienda — registra que usted recomendó una inspección y que el comprador decidió rechazarla, lo cual lo protege. Luego haga clic en",
  "on it below to have the buyer sign.": "a continuación para que el comprador firme.",
  "Generate Waiver": "Generar Renuncia",
  "📝 Letter of Intent (LOI)": "📝 Carta de Intención (LOI)",
  "The standard non-binding first step on a commercial deal. Generate a ready-to-send draft from this deal's details — every clause is pre-written, just confirm the numbers.": "El primer paso estándar no vinculante en una transacción comercial. Genere un borrador listo para enviar con los datos de esta transacción — cada cláusula está prerredactada, solo confirme las cifras.",
  "Create Letter of Intent": "Crear Carta de Intención",
  "✅ Required Documents — all on file": "✅ Documentos Requeridos — todos archivados",
