  "Confidentiality": "Confidencialidad",
  "The parties shall keep the terms of this Letter and their negotiations confidential, except as required by law or as shared with their respective advisors, attorneys and lenders.": "Las partes mantendrán confidenciales los términos de esta Carta y sus negociaciones, excepto según lo exija la ley o se comparta con sus respectivos asesores, abogados y prestamistas.",
  "Expenses": "Gastos",
  "Except as expressly provided, each party shall bear its own costs and professional fees in connection with this transaction.": "Salvo que se indique expresamente, cada parte asumirá sus propios costos y honorarios profesionales relacionados con esta transacción.",
  "Non-Binding Effect": "Efecto No Vinculante",
  "THIS LETTER OF INTENT IS NON-BINDING AND DOES NOT CREATE ANY CONTRACTUAL OBLIGATION. Except for the Exclusivity / No-Shop and Confidentiality paragraphs (which are binding), neither party shall be obligated unless and until a definitive Contract is fully executed by both parties. Either party may negotiate with third parties until a Contract is signed.": "ESTA CARTA DE INTENCIÓN NO ES VINCULANTE Y NO CREA NINGUNA OBLIGACIÓN CONTRACTUAL. Salvo los párrafos de Exclusividad / No Negociar con Terceros y Confidencialidad (que sí son vinculantes), ninguna de las partes estará obligada a menos que y hasta que un Contrato definitivo sea firmado en su totalidad por ambas partes. Cualquiera de las partes puede negociar con terceros hasta que se firme un Contrato.",
  "Governing Law": "Ley Aplicable",
