  "📝 New Addendum to Contract": "📝 Nuevo Anexo al Contrato",
  "The official ACSP-4 form, filled for you — just type the terms. Next step: signatures.": "El formulario oficial ACSP-4, completado por usted — solo escriba los términos. Próximo paso: firmas.",
  "MM/DD/YYYY": "MM/DD/AAAA",
  "Terms of this addendum": "Términos de este anexo",
  "Type anything the parties are agreeing to, e.g.\n1. Closing date is extended to July 31, 2026.\n2. Seller to credit Buyer $2,500 toward closing costs.\n\nLong text automatically continues on an attached page.": "Escriba cualquier acuerdo entre las partes, p. ej.\n1. La fecha de cierre se extiende al 31 de julio de 2026.\n2. El vendedor acreditará al comprador $2,500 para costos de cierre.\n\nEl texto largo continúa automáticamente en una página adjunta.",
  "Create addendum →": "Crear anexo →",
  "It files into Documents, then the signature window opens so you can send it for signing right away.": "Se guarda en Documentos y luego se abre la ventana de firma para que pueda enviarlo a firmar de inmediato.",
  "What should this text box say?\n\nLeave it EMPTY to let the signer type it in when they sign.": "¿Qué debería decir este cuadro de texto?\n\nDéjelo VACÍO para que el firmante lo escriba al momento de firmar.",
  "Place box": "Colocar cuadro",
  "✍️ Signing link sent to ": "✍️ Enlace de firma enviado a ",
  "\n\nThey'll be guided to the exact spot": "\n\nSe le guiará al lugar exacto",
  " you placed.": " que usted colocó.",
  "\n\nWhen everyone has signed, each signed copy (with its signature certificate) appears here in Documents — and you'll get a pop-up.": "\n\nCuando todos hayan firmado, cada copia firmada (con su certificado de firma) aparecerá aquí en Documentos — y recibirá un aviso emergente.",
  "Cancel the outstanding signing links for this document?": "¿Cancelar los enlaces de firma pendientes para este documento?",
  "Cancel links": "Cancelar enlaces",
  "Keep links": "Mantener enlaces",
  "✍️ Get this signed —": "✍️ Que lo firmen —",
  "Each signer gets a private email link to review and sign on their phone or computer. No DocuSign needed.": "Cada firmante recibe un enlace privado por correo para revisar y firmar desde su teléfono o computadora. No se necesita DocuSign.",
  "Signing round in progress": "Ronda de firma en curso",
  "for": "para",
