  "this signer": "el enlace de firma de este firmante",
  "'s signing link to which email?\n\n(Change it here if it was wrong — same link, nothing to redo.)": " a qué correo?\n\n(Cámbielo aquí si estaba equivocado — mismo enlace, no hay que rehacer nada.)",
  "Send link": "Enviar enlace",
  "📧 Signing link sent to ": "📧 Enlace de firma enviado a ",
