  "📧 Resend / fix email": "📧 Reenviar / corregir correo",
  "Opens the document with the completed signatures stamped on it — print it, get the remaining signature by hand, then upload the scan into Documents": "Abre el documento con las firmas completadas estampadas — imprímalo, obtenga la firma restante a mano y luego suba el escaneo a Documentos",
  "🖨️ Print with signatures so far": "🖨️ Imprimir con las firmas hasta ahora",
  "Cancel signing links": "Cancelar enlaces de firma",
  "Signer can't use a computer? Print the copy above, have them sign by hand, upload the scan into Documents, then cancel their remaining link.": "¿El firmante no puede usar una computadora? Imprima la copia de arriba, que firme a mano, suba el escaneo a Documentos y luego cancele su enlace restante.",
  "✅ Everyone signed — look for \"✍️ Signed —": "✅ Todos firmaron — busque \"✍️ Firmado —",
