  "Edit names under the People tab": "Edite los nombres en la pestaña Personas",
  "seller@email.com": "vendedor@email.com",
  "No sellers found on this deal — add them under the People tab first.": "No se encontraron vendedores en esta transacción — agréguelos primero en la pestaña Personas.",
  "✍️ You (": "✍️ Usted (",
  ") sign too — you'll get your own signing link for the broker lines.": ") también firma — recibirá su propio enlace de firma para las líneas del corredor.",
  "Missing details? One tap asks the agent for EVERYTHING still blank — commission (both sides), included appliances, additional terms, HOA info — in a 2-minute form on their phone.": "¿Faltan detalles? Con un solo toque se le pide al agente TODO lo que aún está en blanco — comisión (ambas partes), electrodomésticos incluidos, términos adicionales, información de HOA — en un formulario de 2 minutos en su teléfono.",
  "📨 Sent! The agent got a text + email with a 1-minute form. You'll be notified when they answer — then reopen this wizard and the values fill in.": "📨 ¡Enviado! El agente recibió un mensaje de texto y un correo con un formulario de 1 minuto. Se le notificará cuando responda — luego vuelva a abrir este asistente y los valores se completarán.",
  "📨 Ask the agent": "📨 Preguntar al agente",
  "Listing begins": "Inicio del listado",
  "Ends (termination)": "Finaliza (terminación)",
  "Commission %": "Comisión %",
  "Buyer's broker comp": "Comp. del corredor del comprador",
