  "Personal property included (optional)": "Bienes personales incluidos (opcional)",
  "e.g. refrigerator, washer, dryer": "ej. refrigerador, lavadora, secadora",
  "Currently occupied by a tenant?": "¿Ocupado actualmente por un inquilino?",
  "No — vacant / owner-occupied": "No — vacante / ocupado por el propietario",
  "Yes — tenant occupied": "Sí — ocupado por inquilino",
