  "Listing agreement options (paragraph 6)": "Opciones del contrato de listado (párrafo 6)",
  "Use a lock box system to show and access the Property": "Usar un sistema de caja de seguridad (lock box) para mostrar y acceder a la Propiedad",
  "Withhold verbal offers": "Retener ofertas verbales",
  "Withhold all offers once Seller accepts a sales contract": "Retener todas las ofertas una vez que el Vendedor acepte un contrato de venta",
  "Seller does NOT authorize automated value estimates (AVM) next to the listing": "El Vendedor NO autoriza estimaciones automatizadas de valor (AVM) junto al listado",
  "Seller does NOT authorize third-party comments/reviews on the listing": "El Vendedor NO autoriza comentarios/reseñas de terceros en el listado",
  "Section 13 — Arbitration initials": "Sección 13 — Iniciales de arbitraje",
  "Assign arbitration initials (default) — seller & you initial Section 13": "Asignar iniciales de arbitraje (predeterminado) — el vendedor y usted inician la Sección 13",
  "No one — leave the arbitration initials blank": "Nadie — dejar en blanco las iniciales de arbitraje",
  "Forms in this package": "Formularios en este paquete",
  "AUTO — applies to this deal": "AUTO — aplica a esta transacción",
  "HOA / community name": "Nombre de HOA / comunidad",
  "HOA fee ($)": "Cuota de HOA ($)",
  "Per": "Por",
  "month": "mes",
  "quarter": "trimestre",
  "year": "año",
  "HOA mgmt / contact": "Gestión / contacto de HOA",
  "e.g. Evergreen Mgmt — Zayriliann": "ej. Evergreen Mgmt — Zayriliann",
