  "In Florida the closing is handled by a title company or a real estate attorney. Add them here so they're included in the transaction and receive the welcome email. (You can fill in their name and email below after adding.)": "En Florida, el cierre lo maneja una compañía de títulos o un abogado de bienes raíces. Agréguelo aquí para que se incluya en la transacción y reciba el correo de bienvenida. (Puede completar su nombre y correo electrónico después de agregarlo.)",
