  "🎓 The pre-approval letter proves your buyer is financially qualified. Sellers require it with every offer. Upload a PDF and we'll pull out the key details for your review.": "🎓 La carta de preaprobación demuestra que su comprador está calificado financieramente. Los vendedores la exigen con cada oferta. Suba un PDF y extraeremos los datos clave para su revisión.",
